<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyPortal.php';
require_once __DIR__.'/CompanySalesSchema.php';
require_once __DIR__.'/CompanySalesPreferences.php';

/** Published accepted sales documents only. Contact grants are native and specific to each kind. */
final class CompanyPortalSales
{
    public function __construct(private $db,private string $p,private CompanyPortal $portal){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid prefix');}
    private function rows(string $sql,array $values=[]):array{return IssuerStorage::query($this->db,$sql,$values)->result_array();}
    private static function permission(string $kind):int{return match($kind){'estimates'=>2,'proposals'=>4,default=>throw new DomainException('company_portal_sales_unavailable')};}
    private function tx(callable $operation){CompanySalesSchema::assertValid($this->db,$this->p);return IssuerTransaction::run($this->db,$this->p,['issuers_lock','issuers_registry','issuers_installation_identity','issuers_clients','contacts','clients','contact_permissions','company_sales_documents','issuers_audit'],$operation);}
    private function identity(array $session,int $issuer,string $kind):?array{$who=$this->portal->invoiceIdentity($session,$issuer,true);if(!$who)return null;$rows=$this->rows('SELECT id FROM '.$this->p.'contact_permissions WHERE userid=? AND permission_id=? FOR UPDATE',[$who['contact_id'],self::permission($kind)]);return count($rows)===1?$who:null;}
    private function owned(array $session,int $issuer,int $id):array
    {
        $ref=$this->rows("SELECT kind FROM ".$this->p."company_sales_documents WHERE issuer_id=? AND id=? AND state IN ('accepted','converted') FOR UPDATE",[$issuer,$id])[0]??null;if(!$ref)throw new DomainException('company_portal_sales_unavailable');$who=$this->identity($session,$issuer,$ref['kind']);if(!$who)throw new DomainException('company_portal_sales_unavailable');$r=$this->rows("SELECT * FROM ".$this->p."company_sales_documents WHERE issuer_id=? AND client_id=? AND id=? AND kind=? AND state IN ('accepted','converted') FOR UPDATE",[$issuer,$who['client_id'],$id,$ref['kind']])[0]??null;if(!$r)throw new DomainException('company_portal_sales_unavailable');return [$r,$who];
    }
    public function page(array $session,$issuer,string $kind):?array{$issuer=IssuerPolicy::id($issuer);self::permission($kind);return $this->tx(function()use($session,$issuer,$kind){$who=$this->identity($session,$issuer,$kind);if(!$who)return null;$r=$this->rows("SELECT id,kind,number,state,total,created_at,context_json,origin_hash FROM ".$this->p."company_sales_documents WHERE issuer_id=? AND client_id=? AND kind=? AND state IN ('accepted','converted') ORDER BY id DESC LIMIT 100",[$issuer,$who['client_id'],$kind]);foreach($r as &$row){$context=CompanySalesPreferences::context($row['context_json'],$row['origin_hash'],$issuer,(int)$who['client_id']);$row['formatted_number']=CompanySalesPreferences::presentation($row['kind'],$row['number'],$context)['formatted_number'];unset($row['context_json'],$row['origin_hash']);}unset($row);if(!$this->identity($session,$issuer,$kind))throw new DomainException('company_portal_sales_unavailable');return $r;});}
    public function document(array $session,$issuer,$id):array{$issuer=IssuerPolicy::id($issuer);$id=IssuerPolicy::id($id);return $this->tx(function()use($session,$issuer,$id){[$r,$who]=$this->owned($session,$issuer,$id);$payload=json_decode($r['payload_json'],true,32,JSON_THROW_ON_ERROR);$context=json_decode($r['context_json'],true,32,JSON_THROW_ON_ERROR);if(!is_array($payload)||!is_array($context)||!hash_equals($r['origin_hash'],hash('sha256',json_encode($context,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)))||!hash_equals($r['input_hash'],hash('sha256',json_encode([$r['kind'],$payload],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)))||(int)($context['issuer_id']??0)!==$issuer||(int)($context['recipient']['client_id']??0)!==$who['client_id']||(int)($payload['client_id']??0)!==$who['client_id']||(int)($payload['currency']??0)!==(int)$r['currency'])throw new DomainException('company_portal_sales_unavailable');$this->owned($session,$issuer,$id);return ['id'=>(int)$r['id'],'number'=>(int)$r['number'],'kind'=>$r['kind'],'state'=>$r['state'],'total'=>$r['total'],'payload'=>$payload,'context'=>$context];});}
    public function confirmDownload(array $session,$issuer,$id,string $hash):void{$issuer=IssuerPolicy::id($issuer);$id=IssuerPolicy::id($id);if(!preg_match('/^[a-f0-9]{64}$/D',$hash))throw new DomainException('company_portal_sales_unavailable');$this->tx(function()use($session,$issuer,$id,$hash){[$r,$who]=$this->owned($session,$issuer,$id);$metadata=json_encode(['client_id'=>$who['client_id'],'contact_id'=>$who['contact_id'],'kind'=>$r['kind'],'sha256'=>$hash,'receipt'=>bin2hex(random_bytes(16))],JSON_THROW_ON_ERROR);$event='company_portal_sales_pdf_downloaded';IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(0,?,?,?,?,?)',[$event,$issuer,$id,date('Y-m-d H:i:s'),$metadata]);$audit=(int)$this->db->insert_id();if(!$audit||!$this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND subject_id=? AND metadata_json=?',[$audit,$issuer,$id,$metadata]))throw new RuntimeException('issuer_portal_write_unconfirmed');$this->owned($session,$issuer,$id);});}
}
